Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "description": "Agent performance against monthly target",
  "data": {
    "name": "dataset"
  },
  "transform": [
    {
      "calculate": "datum[''APE Target''] == 0 ? null : datum[''APE''] / datum[''APE Target'']",
      "as": "performanceRatio"
    },
    {
      "calculate": "datum.performanceRatio >= 1 ? ''Above target'' : datum.performanceRatio >= 0.9 ? ''On track'' : ''Below target''",
      "as": "performanceBand"
    }
  ],
  "encoding": {
    "y": {
      "field": "agent_name",
      "type": "nominal",
      "sort": "-x",
      "title": null,
      "axis": {
        "labelLimit": 180,
        "labelFontSize": 11
      }
    }
  },
  "layer": [
    {
      "mark": {
        "type": "bar",
        "color": "#d9dee5",
        "size": 14
      },
      "encoding": {
        "x": {
          "field": "APE Target",
          "type": "quantitative",
          "title": "APE vs Monthly Target",
          "axis": {
            "format": ",.0f",
            "grid": true
          }
        }
      }
    },
    {
      "mark": {
        "type": "bar",
        "size": 10,
        "cornerRadiusEnd": 2
      },
      "encoding": {
        "x": {
          "field": "APE",
          "type": "quantitative"
        },
        "color": {
          "field": "performanceBand",
          "type": "nominal",
          "scale": {
            "domain": ["Above target", "On track", "Below target"],
            "range": ["#1a9850", "#f39c12", "#d73027"]
          },
          "legend": {
            "title": "Performance"
          }
        },
        "tooltip": [
          {
            "field": "agent_name",
            "type": "nominal",
            "title": "Agent"
          },
          {
            "field": "APE",
            "type": "quantitative",
            "title": "APE",
            "format": "$,.0f"
          },
          {
            "field": "APE Target",
            "type": "quantitative",
            "title": "Target",
            "format": "$,.0f"
          },
          {
            "field": "performanceRatio",
            "type": "quantitative",
            "title": "Achievement",
            "format": ".0%"
          },
          {
            "field": "performanceBand",
            "type": "nominal",
            "title": "Status"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "dx": 6,
        "fontSize": 10,
        "color": "#18304b"
      },
      "encoding": {
        "x": {
          "field": "APE",
          "type": "quantitative"
        },
        "text": {
          "field": "performanceRatio",
          "type": "quantitative",
          "format": ".0%"
        }
      }
    }
  ],
  "width": 1500,
  "height": {
    "step": 18
  },
  "config": {
    "view": {
      "stroke": null
    },
    "axis": {
      "titleFont": "Segoe UI Semibold",
      "labelFont": "Segoe UI"
    }
  }
}'
